  ('地元の制作会社のほうがいいですか？', '撮影や打ち合わせで会えるのは安心です。ただ、オンラインでも十分に進められるので、場所より「業種の理解」と「作ったあとの対応」で選ぶのがおすすめです。'),
  ('個人で活動している制作者に頼んでも大丈夫ですか？', '費用を抑えやすく、やりとりも早いことが多いです。ただ、連絡がつかなくなったときに困らないよう、ドメインとサーバーは自社の名義にしておくことが特に大切です。'),
  ('制作会社に何を用意して相談すればいいですか？', '今のサイトのアドレス（あれば）、載せたい内容のメモ、参考にしたいサイト、予算と公開したい時期があると、話が早く進みます。何も決まっていなくても相談はできます。'),
