  ('llms.txtは英語で書かないといけませんか？', '日本語で書いてかまいません。ホームページが日本語なら、同じ言葉で書いたほうが、画面の内容と合わせやすくなります。文字化けしないよう、文字コードはUTF-8で保存します。'),
