  ('リニューアルすると、検索の順位は下がりますか？', '古いアドレスから新しいページへの案内の設定をし、よく見られていたページの内容を残せば、影響はできるだけ小さくできます。この作業が見積りに含まれているかを確かめましょう。'),
  ('会社のメールアドレスは変わりますか？', '今のドメインをそのまま使えば、メールアドレスは変わりません。サーバーを切り替える場合は、メールが止まらないように段取りを決めてから進めます。'),
