  ('月額制のホームページをやめたら、サイトはどうなりますか？', 'サービスによって違います。サイトが見られなくなり、データも受け取れないことがあります。デザインやプログラムの権利がサービス側にあることも多いので、契約の前に、やめたあとにデータとドメインを受け取れるかを確かめておきましょう。'),
