  ('WordPressを使うと、検索で有利になりますか？', 'WordPressを使っているだけで、有利になることはありません。検索で見つけてもらえるかどうかは、ページに書いてある中身で決まります。記事を足しやすいので、続けて書く会社には向いています。'),
  ('今のWordPressのホームページが、何年も更新されていません。大丈夫ですか？', '本体や部品が古いままだと、安全上の弱いところが残っていることがあります。まず、データの控えを取ったうえで、今の状態を制作会社に確かめてもらうのがおすすめです。'),
