  ('テーマは、無料のものでも大丈夫ですか？', '大丈夫です。無料か有料かより、更新が続いているか、使っている人が多いか、スマホで見やすいかで選ぶことが大切です。困ったときに相談できる窓口がほしい場合は、有料のテーマも候補になります。'),
  ('WordPressで作れば、問い合わせは増えますか？', 'WordPressは更新しやすくする道具なので、それだけで問い合わせは増えません。実績や対応できる仕様など、お客様が判断に使う情報を足し続け、アクセス解析を見て直していくことで、問い合わせにつながります。'),
