  ('ホームページが古くても、SEO対策はできますか？', 'できることはあります。ただ、スマホで見づらい、httpsになっていない、自分たちで直せないといった状態なら、作り直したほうが早い場合もあります。目安は、ホームページのリニューアルを考えたい6つのサインの記事で紹介しています。'),
