{
 'slug': 'nocode-migration',
 'category': 'renewal',
 'title': 'ホームページをノーコードから乗り換えるには？移行の手順と注意点',
 'description': 'Studioなどのノーコードツールで作ったホームページの乗り換えを考えている会社へ。乗り換える前に確かめること、乗り換え先の選び方、移すものの一覧、301リダイレクトとドメインを止めずに切り替える順番、乗り換えずに守りを固める方法を、制作する側の目線でまとめました。',
 'date': '2026-10-19',
 'points': ['乗り換えを考える前に確かめることと、乗り換え先3つの比べ方', '移すもの（文章・画像・CMS・フォーム・ドメイン・メールなど）と手順', 'URLが変わるときの301リダイレクトと、ドメインを止めずに切り替える順番'],
 'body': '''
<p>2026年10月16日、ノーコードでホームページを作れるサービス「Studio」を運営するStudio株式会社が、不正アクセスによって利用者の情報が流出した可能性があると発表しました。これをきっかけに、「ほかのサービスやWordPressに乗り換えたほうがいいのだろうか」と考え始めた社長や担当者の方もいると思います。</p>
<p>結論から言うと、乗り換えるかどうかは、落ち着いて判断すれば大丈夫です。まずは今回の件で求められている対応を済ませることが先です。そのうえで、乗り換える理由がはっきりしているなら、この記事の順番で準備を進めてください。乗り換えは、移すものや手順を知らずに進めると、問い合わせフォームが止まったり、検索からの訪問が減ったりすることがあります。この記事では、ノーコードツールからの乗り換えを考えるときに確かめること、乗り換え先の選び方、移すもの、手順、注意点を、制作する側の目線でまとめます。</p>
{{fig:nocode-migration}}

<h2 id="first">乗り換えを考える前に、まず今回の対応を済ませる</h2>
<p>乗り換えを考えるのは、今回の対応が終わってからにしましょう。理由はかんたんで、<b>サイトを別のサービスに移しても、すでに流出した可能性のある情報は戻らない</b>からです。パスワードの変更、外部サービスのAPIキーの差しかえ、フォームで個人情報を集めていた場合の本人への通知の検討などは、乗り換えるかどうかに関係なく、今のアカウントで進める必要があります。</p>
<p>また、乗り換えの準備を始めてから旧サイトを止めるまでには、少なくとも数週間はかかります。その間も今のサイトは動き続けるので、守りを固めておくことには意味があります。何をすればよいかは、<a href="../studio-unauthorized-access/">Studioの不正アクセス・個人情報流出｜利用企業が今すぐやること</a>にまとめています。対応はStudioの公式のお知らせで、最新の内容を確かめながら進めてください。</p>
<h3>どのサービスでも、事故は起こりうる</h3>
<p>知っておきたいのは、不正アクセスや情報の流出は、特定のサービスだけで起きることではないという点です。ほかのノーコードツールでも、WordPressでも、レンタルサーバーでも、制作会社が自前で作ったシステムでも、起こる可能性はあります。WordPressは自由度が高い分、本体やプラグイン（あとから足す機能）の更新を自社や制作会社が続けないと、弱いところを突かれやすくなります。</p>
<p>大切なのは、「どのサービスなら絶対に安全か」を探すことではなく、何かあったときに早く気づけて、すぐに対応できる体制を作っておくことです。乗り換え先を選ぶときも、この目線を持っておくと判断しやすくなります。</p>

<h2 id="reason">乗り換える理由を、言葉にしておく</h2>
<p>次に、なぜ乗り換えたいのかを紙に書き出してみましょう。理由がはっきりしないまま乗り換えると、移ったあとで「前のほうがよかった」となりがちです。よくある理由は次のようなものです。</p>
<ul>
<li><b>安心して使い続けられるか不安になった</b>：今回のような出来事をきっかけに、会社としての方針を見直したい</li>
<li><b>社内で更新できない</b>：作った人が辞めた、操作が難しくて誰も触れない</li>
<li><b>やりたいことができない</b>：記事の数が増えて管理しにくい、採用ページや多言語を足したい、外部のシステムとつなぎたい</li>
<li><b>費用が合わない</b>：プランの改定で毎月の費用が上がった、使っていない機能に払っている</li>
<li><b>制作会社との関係を見直したい</b>：アカウントを制作会社が持っていて、自社で中身を確かめられない</li>
</ul>
<p>「不安になった」だけが理由なら、乗り換えずに今のツールで守りを固めるほうが、手間も費用も少なくて済むことがあります。この選び方は、記事の後半でくわしく書きます。一方、「更新できない」「やりたいことができない」が理由なら、乗り換えやリニューアルを考えるよい機会です。ほかの見直しのきっかけは、<a href="../renewal-signs/">ホームページのリニューアルを考えたい6つのサイン</a>も参考にしてください。</p>

<h2 id="contract">契約・プラン・更新日を確かめる</h2>
<p>乗り換えを決める前に、今の契約を確かめておきます。ここを見落とすと、旧サイトが思ったより早く止まったり、反対に使わない期間の費用を払い続けたりします。</p>
<table class="art-table">
<tr><th>確かめること</th><th>なぜ必要か</th></tr>
<tr><td>アカウントの持ち主</td><td>自社か制作会社か。解約やデータの書き出しは、持ち主でないとできないことが多い</td></tr>
<tr><td>今のプランと支払い方法</td><td>月払いか年払いか。プランによって使える機能（リダイレクトなど）が違う</td></tr>
<tr><td>次の更新日</td><td>解約やプラン変更がいつ反映されるかが決まる</td></tr>
<tr><td>解約したときのサイトの扱い</td><td>すぐ非公開になるのか、更新日まで表示されるのか</td></tr>
<tr><td>ドメインの契約先と名義</td><td>ドメインを持ったまま移れるか。ツールで取ったドメインかどうか</td></tr>
</table>
<p>Studioの場合、公式ヘルプでは次のように説明されています。</p>
<ul>
<li>プランのダウングレード（下のプランへの変更や、Freeプランへの切り替え）は、申し込んですぐではなく、<b>次回の契約更新日に切り替わる</b>。それまでは今のプランの機能を使える</li>
<li>更新日は［プラン＆お支払い］ダッシュボードで確かめられる</li>
<li>切り替わる時点で、変更先のプランで使えない機能を使っていると、サイトが自動で非公開になることがある</li>
<li>課金だけを止めたい場合は、退会ではなくダウングレードで対応することがすすめられている。退会したアカウントは元に戻せず、原則として同じメールアドレスで登録し直せない</li>
<li>支払いをしているオーナーがほかのオーナーのいない状態で退会すると、その時点で公開サイトとプレビューが非公開になる</li>
</ul>
<p>つまり、<b>新しいサイトの公開より先に退会や解約をしてしまうと、サイトが表示されない期間ができてしまう</b>おそれがあります。解約の手続きは、新しいサイトの公開と確認が終わってから、更新日に合わせて行うのが安全です。Wix、ペライチなどほかのツールでも、解約後の扱いはサービスごとに違うので、それぞれの公式ヘルプで確かめてください。</p>
<p>アカウントを制作会社が持っている場合は、まず持ち主を自社に移してもらえるか相談します。乗り換え全体の進め方は、<a href="../change-web-company/">ホームページの制作会社を乗り換える手順</a>でも紹介しています。</p>

<h2 id="choose">乗り換え先の選び方｜3つの方法を比べる</h2>
<p>乗り換え先は、大きく分けて3つあります。別のノーコードツールに移す、WordPressで作る、制作会社に作り直しを頼む、の3つです。どれがよいかは、社内で誰が更新するか、どこまで自由に作りたいか、管理にどれだけ手をかけられるかで変わります。</p>
<table class="art-table">
<tr><th></th><th>別のノーコードツール</th><th>WordPress</th><th>制作会社に作り直しを頼む</th></tr>
<tr><td>向いている会社</td><td>ページ数が少なく、社内で文章や写真を差しかえたい</td><td>記事やお知らせを多く載せたい、機能を足していきたい</td><td>社内に作る人がいない、この機会に中身から見直したい</td></tr>
<tr><td>サーバーや更新の管理</td><td>サービス側が行う</td><td>自社か制作会社で、本体・プラグインの更新を続ける必要がある</td><td>作り方による。誰が管理するかを契約で決める</td></tr>
<tr><td>自由度</td><td>ツールでできる範囲まで</td><td>高い</td><td>作り方による</td></tr>
<tr><td>手間</td><td>作り直しは自分たちで行う</td><td>設定や作り直しに手間がかかる</td><td>原稿や写真の用意、確認が中心</td></tr>
<tr><td>気をつけたいこと</td><td>また乗り換えるときに、データを書き出せないことがある</td><td>更新を止めると、弱いところを突かれやすい</td><td>アカウントやドメインの名義を自社にしておく</td></tr>
</table>
<p>どの方法でも、<b>デザインや中身を今のツールからそのまま持っていけるとは限らない</b>と考えておきましょう。後で説明するとおり、ノーコードツールの多くは、サイトをまるごと書き出してほかの場所で動かすことができません。乗り換えは「引っ越し」というより、「同じ内容で建て直す」作業に近いです。</p>
<p>WordPressが自社に合うかどうかは、<a href="../wordpress-necessary/">ホームページにWordPressは必要か</a>で整理しています。社内で作り直す場合の進め方は、<a href="../homepage-diy/">ホームページを自分で作るには？</a>も参考にしてください。制作会社に頼む場合の費用の考え方は、<a href="../renewal-cost/">ホームページのリニューアル費用の相場と内訳</a>にまとめています。</p>
<h2 id="items">移すものの一覧</h2>
<p>乗り換えでは、ページの見た目より先に、「何を移さなければいけないか」を洗い出すことが大切です。見落としやすいのは、ページの外にあるもの（ドメイン、メール、アクセス解析、外部サービスのリンク）です。</p>
<table class="art-table">
<tr><th>移すもの</th><th>やること</th></tr>
<tr><td>ページの文章</td><td>全ページの文章をコピーして、ページごとにまとめておく</td></tr>
<tr><td>画像</td><td>元のデータ（撮影した写真、ロゴのデータ）を探す。なければ公開中のページから保存する</td></tr>
<tr><td>CMSの記事（お知らせ・実績・ブログなど）</td><td>書き出せるか確かめる。できなければ1件ずつ移す</td></tr>
<tr><td>フォームの回答データ</td><td>過去の問い合わせを書き出して、社内で保管する</td></tr>
<tr><td>フォームの設定</td><td>入力項目、通知先のメールアドレス、自動返信の文面を控える</td></tr>
<tr><td>ドメイン</td><td>契約先、名義、更新日、DNSの設定を確かめる</td></tr>
<tr><td>メール</td><td>会社のメールアドレスが、どのサービスで動いているか確かめる</td></tr>
<tr><td>アクセス解析</td><td>Googleアナリティクスや Search Console の設定を新しいサイトに入れ直す</td></tr>
<tr><td>Googleビジネスプロフィールなど外部のリンク</td><td>ホームページのURLが変わる場合は、登録しているURLを書きかえる</td></tr>
</table>
<h3>ページの文章と画像</h3>
<p>Studioの公式ヘルプでは、<b>サイトのデータをほかのサービスへ移すための書き出し機能はない</b>と説明されています。デザイン、ページの構成や設定、公開サイトのHTMLなどのソースコード、Studio CMSのデータは、いずれも書き出せません。移行先で作り直すことになります。</p>
<p>Wixも、公式ヘルプで、Wixのサイトを外部のサーバーに書き出すことはできないと説明しています。ほかのツールを使っている場合も、まず公式ヘルプで「書き出し」「エクスポート」について確かめてください。</p>
<p>そのため、文章はページごとにコピーして、表計算ソフトや文書ファイルにまとめておきます。画像は、できれば撮影したときの元のデータを使います。公開中のページから保存した画像は、小さく圧縮されていることがあるためです。乗り換えのついでに、古くなった文章や写真を見直すのもおすすめです。用意のしかたは、<a href="../homepage-photo-text/">ホームページに載せる写真と文章の用意のしかた</a>でまとめています。</p>
<h3>CMSの記事</h3>
<p>お知らせや施工事例、ブログなどの記事を、ツールのCMS（記事を管理する機能）で作っている場合は、件数を数えておきます。Studio CMSのデータは書き出せないので、移行先で1件ずつ登録し直します。件数が多い場合は、それだけで大きな作業になるので、見積りや日程に入れておきましょう。古い記事を移さずに整理するのも、ひとつの方法です。ただし、検索から訪問が多い記事は残して、URLの対応（後で説明します）もしておきます。</p>
<h3>フォームの回答データ</h3>
<p>Studioでは、フォームの回答は、フォームのダッシュボードからCSVファイルとして書き出せると公式ヘルプで説明されています。解約すると見られなくなるおそれがあるので、乗り換えの前に書き出して、社内の決まった場所で保管しておきましょう。お客様や応募者の個人情報が含まれるので、保管する場所と、見られる人を決めておくことが大切です。</p>
<h3>フォームの設定</h3>
<p>入力する項目、必須かどうか、通知先のメールアドレス、自動返信のメールの文面は、新しいサイトで作り直します。画面を写しておくか、項目を書き出しておくと、作り直すときに迷いません。乗り換えの機会に、本当に必要な項目だけにしぼるのもおすすめです。</p>
<h3>ドメインとメール</h3>
<p>独自ドメインを使っている場合、ドメインそのものは、ドメインを取った会社（登録事業者）で契約していることがほとんどです。ツールは、そのドメインで表示されるように設定を向けているだけ、という形が一般的です。まず、ドメインの契約先と名義、更新日、DNS（ドメインの行き先を決める設定）をどこで管理しているかを確かめます。仕組みは、<a href="../domain-server/">ドメインとサーバーとは？</a>で紹介しています。</p>
<p>会社のメールアドレスが同じドメインで動いている場合は、メールの設定には触れずに、ホームページの行き先だけを切り替えるのが基本です。ここを間違えると、メールが届かなくなります。</p>
<h3>アクセス解析と外部のリンク</h3>
<p>GoogleアナリティクスやSearch Consoleの設定は、新しいサイトに入れ直します。Googleビジネスプロフィール、SNSのプロフィール、求人サイトなどに載せているURLも、変わる場合は書きかえます。</p>

<h2 id="steps">乗り換えの手順</h2>
<p>乗り換えは、次の順番で進めると、ホームページが止まる時間をなくせます。</p>
<ol>
<li><b>今のサイトの全ページを一覧にする</b>：ページの名前とURLを表にまとめます。よく見られているページには印をつけておきます。</li>
<li><b>移すものを集める</b>：文章、画像、CMSの記事、フォームの回答（CSV）を、社内の決まった場所に保存します。</li>
<li><b>新しいサイトの構成を決める</b>：残すページ、まとめるページ、新しく作るページを決めます。ページ数の考え方は、<a href="../homepage-pages/">ホームページは何ページ必要？</a>を参考にしてください。</li>
<li><b>URLの対応表を作る</b>：古いURLと新しいURLを1対1で並べます。次の章で説明する転送の設定に使います。</li>
<li><b>新しいサイトを作り、仮のURLで確かめる</b>：公開する前に、スマホとパソコンの両方で表示とフォームの送信を確かめます。</li>
<li><b>切り替える</b>：ドメインの行き先を新しいサイトに向けます。</li>
<li><b>公開後に確かめる</b>：古いURLで開いて、新しいページに移るか、フォームが届くかを確かめます。</li>
<li><b>今のツールの契約を整理する</b>：新しいサイトが問題なく動いていることを確かめてから、プランの変更や解約をします。</li>
</ol>
<p>大事なのは、<b>今のツールの解約を一番最後にする</b>ことです。先に解約すると、新しいサイトが公開できるまでの間、ホームページが見られなくなります。</p>

<h2 id="redirect">URLが変わるときは、301リダイレクトを設定する</h2>
<p>新しいサイトでページのURLが変わる場合は、古いURLを開いた人を新しいURLへ自動で移す設定（リダイレクト）をします。これをしないと、検索結果やブックマーク、名刺のQRコードから来た人が「ページが見つかりません」という画面にたどり着いてしまいます。</p>
<p>Googleは、URLが変わるサイトの移転について、次のようなことをすすめています。</p>
<ul>
<li>古いURLから新しいURLへ、サーバー側で恒久的なリダイレクト（301など）を設定する</li>
<li>リダイレクトは、できるだけ長く、一般的には1年以上残しておく</li>
<li>サイトの中のリンクを、新しいURLに書きかえる</li>
<li>新しいURLのサイトマップを作り、Search Consoleで送る</li>
</ul>
<p>リダイレクトは、移った先のサイト（新しいサーバーやツール）で設定します。乗り換え先がリダイレクトの設定に対応しているかは、選ぶ段階で確かめておきましょう。ドメインごと変わる場合は、Search Consoleの「アドレス変更ツール」も使います。</p>
<p>ドメインもページのURLも変わらない場合は、リダイレクトはいりません。ただ、ノーコードツールと乗り換え先とでは、URLの付け方が違うことがよくあります。対応表を作って、1ページずつ確かめるのが確実です。</p>

<h2 id="domain-order">ドメインを止めずに切り替える順番</h2>
<p>ドメインの切り替えは、乗り換えでいちばん気をつけたい作業です。次の順番を守ると、ホームページもメールも止めずに進められます。</p>
<table class="art-table">
<tr><th>順番</th><th>やること</th><th>気をつけること</th></tr>
<tr><td>1</td><td>DNSを管理している場所と、今の設定を控える</td><td>メールの設定（MXレコードなど）も含めて、画面を写しておく</td></tr>
<tr><td>2</td><td>新しいサイトを、仮のURLで完成させる</td><td>フォームの送信、表示、リンクを確かめておく</td></tr>
<tr><td>3</td><td>ホームページの行き先の設定だけを、新しいサイトに書きかえる</td><td>メールの設定には触れない</td></tr>
<tr><td>4</td><td>新しいサイトが表示されるかを確かめる</td><td>切り替わるまでに時間がかかることがある</td></tr>
<tr><td>5</td><td>httpsで表示されるかを確かめる</td><td>証明書の設定が済んでいるか（<a href="../not-secure-ssl/">「保護されていない通信」と出るのはなぜ？</a>）</td></tr>
<tr><td>6</td><td>しばらく様子を見てから、今のツールの契約を整理する</td><td>独自ドメインの設定を外す手順は、ツールの公式ヘルプで確かめる</td></tr>
</table>
<p>切り替えは、問い合わせの少ない日や時間を選び、作業する人と、確かめる人を決めておくと安心です。制作会社に頼む場合も、ドメインの管理画面に入れる情報が社内にあるかを先に確かめておきましょう。</p>

<h2 id="troubles">乗り換えで、よくある困りごと</h2>
<h3>解約したら、過去の問い合わせが見られなくなった</h3>
<p>フォームの回答を書き出す前に解約してしまうと、過去の問い合わせを確かめられなくなることがあります。解約の前に、回答のCSVを必ずダウンロードしておきましょう。</p>
<h3>メールが届かなくなった</h3>
<p>ドメインの設定を書きかえるときに、メールの設定まで変えてしまうと起こります。切り替えの前に今の設定を控え、メールに関わる設定には触れないようにします。</p>
<h3>検索からの訪問が減った</h3>
<p>URLが変わったのにリダイレクトをしていない、よく見られていたページを消してしまった、といったときに起こりやすくなります。対応表を作り、残すページを先に決めておくことで防げます。</p>
<h3>思ったより時間がかかった</h3>
<p>書き出せないデータは、新しいサイトで作り直すことになります。とくにCMSの記事が多いと、登録し直すだけで時間がかかります。件数を数えてから日程を決めましょう。</p>
<h3>見た目は同じなのに、更新しにくくなった</h3>
<p>乗り換え先によって、更新のしかたは大きく変わります。誰が、何を、どのくらい更新するかを先に決め、それに合う乗り換え先を選ぶことが大切です。</p>

<h2 id="stay">乗り換えずに、今のツールで守りを固める方法もある</h2>
<p>乗り換えには、時間も費用もかかります。今のツールの使い勝手に満足しているなら、乗り換えずに、使い方を見直すのも十分な選択です。どのサービスを使っていても、事故は起こりえます。大切なのは、万一のときの影響を小さくしておくことです。</p>
<ul>
<li><b>パスワードを使い回さない</b>：ツールごとに別のパスワードにします。</li>
<li><b>フォームの回答を、ツールにため続けない</b>：必要な回答はCSVで書き出して社内で保管し、ツールの中の古い回答は定期的に完全に削除します。Studioでは、ゴミ箱に移しただけでは削除されないので、「完全に削除」まで行います。</li>
<li><b>外部のサービスの鍵を整理する</b>：使っていないAPIキーや連携は外し、使っているものは定期的に切り替えます。</li>
<li><b>編集できる人を最小限にする</b>：退職した人や、もう関わっていない制作会社のアカウントが残っていないか確かめます。</li>
<li><b>お知らせを見落とさない</b>：ツールからの大事な知らせが届くメールアドレスを、社内の誰かが必ず見られるものにしておきます。</li>
</ul>
<p>こうした見直しは、乗り換える場合も、乗り換えない場合も、やっておいて損はありません。</p>

<h2 id="cost">乗り換えの費用と期間の考え方</h2>
<p>乗り換えの費用と期間は、ページ数、CMSの記事の数、デザインを作り直すかどうかで変わります。新しく作るときとの違いは、今のサイトの確認、内容の移しかえ、URLの引き継ぎといった作業が加わることです。くわしくは、<a href="../renewal-cost/">ホームページのリニューアル費用の相場と内訳</a>で紹介しています。</p>
<p>マツケンスタジオでは、1ページ（LP）は15万円から、2〜5ページは30万円から、6〜20ページは60万円からが目安で、会社のホームページの期間は1〜3か月ほどです。作り直す場合も、ドメインとサーバーはお客様の名義のままで進め、最初の相談から公開後まで同じ担当が見ます。制作会社を変えるときの手順は、<a href="../change-web-company/">ホームページの制作会社を乗り換える手順</a>もあわせてご覧ください。</p>
<p>自分たちで乗り換え先のツールを使って作り直す場合の考え方は、<a href="../homepage-diy/">ホームページを自分で作るには？</a>で紹介しています。</p>

<h2 id="consult">乗り換えを相談するときに伝えること</h2>
<p>制作会社に乗り換えを相談するときは、次のことが分かると、見積りと日程が具体的になります。すべてそろっていなくても大丈夫です。</p>
<ul>
<li>今使っているツールの名前と、契約しているプラン、更新日</li>
<li>今のサイトのURLと、おおよそのページ数</li>
<li>CMSで管理している記事の種類と件数</li>
<li>フォームの数と、集めている項目</li>
<li>ドメインの契約先と、管理画面に入れる人がいるか</li>
<li>会社のメールが、どのサービスで動いているか</li>
<li>乗り換えたい理由と、公開したい時期</li>
</ul>
<p>とくに、乗り換えたい理由がはっきりしていると、作り直すべきところと、そのままでよいところを分けて考えられます。理由が「今回の事故が不安だから」だけの場合は、乗り換えずに守りを固める方法と、費用や手間を比べてから決めましょう。</p>

<h2 id="summary">まとめ</h2>
<p>ノーコードツールからの乗り換えは、まず今回のような事故への対応を済ませ、乗り換える理由をはっきりさせるところから始めます。Studioのように、サイトのデータを書き出せないツールもあるため、文章や画像、CMSの記事は移行先で作り直す前提で計画し、フォームの回答だけは解約の前に必ず書き出しておきましょう。URLが変わるなら301リダイレクトを設定し、ドメインはメールの設定に触れずに、ホームページの行き先だけを切り替えます。今のツールの解約は最後に。乗り換えるかどうかは、落ち着いて判断すれば十分です。</p>
''',
 'faq': [
  ('Studioで作ったサイトを、そのまま別のサービスに移せますか？', 'Studioの公式ヘルプでは、サイトのデータをほかのサービスへ移すための書き出し機能は提供していないと説明されています。デザイン、ページの情報、ソースコード、Studio CMSのデータは書き出せないため、移行先で作り直すことになります。'),
  ('過去のフォームの回答は、乗り換えたあとも残せますか？', 'Studioでは、フォームの回答をフォームのダッシュボードからCSVファイルとしてダウンロードできます。解約すると見られなくなるおそれがあるので、乗り換えの前に書き出し、社内の決まった場所で保管しておきましょう。'),
  ('乗り換えると、ホームページのアドレスは変わりますか？', '独自ドメインを使っていれば、ドメインはそのまま使えます。ただし、ページごとのURLの付け方が変わることがあるので、古いURLと新しいURLの対応表を作り、変わるページには301リダイレクトを設定します。'),
  ('乗り換えのとき、会社のメールは止まりませんか？', 'ドメインの設定のうち、ホームページの行き先だけを書きかえ、メールに関わる設定に触れなければ、メールは止まりません。切り替えの前に今の設定を控えておくと安心です。'),
  ('今回の不正アクセスを受けて、すぐに乗り換えたほうがいいですか？', 'まずは、パスワードの変更やAPIキーの切り替えなど、今回の対応を済ませることが先です。乗り換えには時間も費用もかかるので、続報の内容や自社の使い方を見て、落ち着いて判断すれば十分です。'),
  ('乗り換え先は、どう選べばいいですか？', '誰が、何を、どのくらい更新するかで選びます。自分たちで手軽に直したいなら別のノーコードツール、記事を多く書くならWordPress、更新や管理も任せたいなら制作会社への依頼が向いています。'),
 ],
},
