  ('改ざんされた部分を消せば、それで終わりですか？', '見えている部分を消しても、入口になった弱いところや、裏に仕込まれたファイルが残っていれば、また書きかえられます。記録を残したうえで、原因を調べ、きれいな状態に戻し、本体やプラグインを新しくしてから再公開する、という順番で進めましょう。'),
  ('サイトは止めたほうがいいですか？', '訪れた人が偽のサイトへ移されたり、悪いプログラムを受け取ったりするおそれがあるため、一時的に止めることをおすすめします。総務省の案内でも、復旧に時間がかかる場合は一時的に非公開にすることを検討するよう書かれています。メンテナンスの表示に、電話などの連絡先を書いておくと親切です。'),
  ('Search Consoleの再審査は、どのくらいで終わりますか？', 'Googleのヘルプでは、ほとんどの再審査は数日から数週間かかるとされています。目安として、マルウェアは数日、スパムを含むハッキングは最長で数週間かかることがあると案内されています。申し込む前に、被害を取り除き、弱いところを直して、きれいなサイトを公開に戻しておく必要があります。'),
