POSTS_BATCH13 = [
{
 'slug': 'review-reply',
 'category': 'seo',
 'title': 'Google口コミの返信例文｜BtoBの会社向け、良い・悪い口コミの返し方と集め方',
 'description': 'Googleマップの口コミへの返信例文を、製造業・工務店・運送業・採用など現場のある会社向けにまとめました。返信の基本、星だけの口コミ、悪い口コミへの返し方、事実と違う口コミの報告、口コミの増やし方とやってはいけないことも紹介します。',
 'date': '2026-10-24',
 'points': ['口コミに返信する理由と、返信の基本（早さ・名前・個人情報・宣伝）', '良い口コミ・星だけの口コミ・悪い口コミへの返信例文（業種別）', '事実と違う口コミの報告のしかたと、決まりを守った口コミの集め方'],
 'body': '''
<p>「Googleマップに口コミが付いたけれど、何と返せばいいか分からない」「厳しい口コミが書かれて、そのままにしている」。現場のある会社の社長や担当者から、よく聞く悩みです。口コミの返信例文を探すと、飲食店やお店向けのものが多く、取引先や施主、荷主、求職者からの口コミにはそのまま使いにくいことがあります。</p>
<p>この記事では、ホームページやGoogleマップの整備を手伝う側の目線で、製造業・建設業・工務店・運送業など、BtoBの会社でも使いやすい返信の例文をまとめました。返信の基本、悪い口コミへの向き合い方、事実と違う口コミの報告のしかた、決まりを守った口コミの集め方まで、Googleビジネスプロフィールのヘルプとコンテンツポリシーで確かめた内容をもとに紹介します。</p>
{{fig:review-reply}}

<h2 id="why">口コミに返信する理由</h2>
<p>口コミへの返信は、書いてくれた人へのお礼であると同時に、あとからその口コミを読む人に向けたメッセージでもあります。</p>
<ul>
<li><b>依頼を考えている人が読んでいる</b>：新しい取引先や施主、求職者は、問い合わせの前にGoogleマップで会社を調べ、口コミと返信を読みます。返信があると、「きちんと対応してくれる会社だ」と伝わります。</li>
<li><b>書いた人に届く</b>：Googleのヘルプでは、返信が公開されると、口コミを書いた人に通知が届くと案内されています。お礼が直接届くので、関係づくりにもつながります。</li>
<li><b>Googleも返信を勧めている</b>：Googleは、ビジネスプロフィールを整えるためにできることの一つとして、口コミに返信することを挙げています。</li>
</ul>
<p>反対に、口コミが並んでいるのに返信が一つもないと、「見ていないのかな」「連絡しても返事が遅いのかな」と受け取られることがあります。とくに厳しい口コミをそのままにしておくと、会社側の考えが何も伝わりません。</p>

<h2 id="before">返信する前に知っておきたいこと</h2>
<h3>返信できるのは、オーナー確認を済ませた人だけ</h3>
<p>Googleのヘルプでは、口コミに返信するには、ビジネスのオーナー確認が必要とされています。オーナー確認とは、「この会社の持ち主（管理する立場）は自分です」とGoogleに認めてもらう手続きです。まだの場合は、先に済ませましょう。登録やオーナー確認の流れは、<a href="../google-business-profile/">Googleマップで選ばれる会社の共通点｜ビジネスプロフィールの整え方</a>にまとめています。</p>
<h3>返信は会社の名前で表示される</h3>
<p>返信は、担当者個人の名前ではなく、会社（ビジネス）からの返信として表示されます。誰が書いても会社の言葉として読まれるので、社内で書き方をそろえておくと安心です。</p>
<h3>表示されるまでに時間がかかることがある</h3>
<p>返信は、Googleの審査を経てから表示されます。ヘルプでは、通常は10分以内ですが、最長で30日ほどかかる場合もあると案内されています。書いたのにすぐ出てこなくても、慌てて何度も書き直す必要はありません。</p>
<h3>あとから直したり、消したりできる</h3>
<p>公開したあとの返信は、編集や削除ができます。誤字や、書きすぎたことに気づいたら直しましょう。また、口コミを書いた人も、返信を読んだあとに自分の口コミを変えられます。丁寧な返信をきっかけに、内容を書き直してもらえることもあります。</p>

<h2 id="basics">返信の基本（4つのポイント）</h2>
<table class="art-table">
<tr><th>ポイント</th><th>考え方</th></tr>
<tr><td>早さ</td><td>なるべく早く返す。とくに厳しい口コミは、社内で事実を確かめたうえで、間を空けすぎない。</td></tr>
<tr><td>名前で呼ぶか</td><td>表示名で呼ぶのは問題ないが、本名か分からない表示名もある。迷ったら「ご投稿いただいた方へ」などでもよい。</td></tr>
<tr><td>個人情報</td><td>お客様の会社名、現場の住所、工事の内容、注文の中身など、相手が特定されることは書かない。</td></tr>
<tr><td>宣伝</td><td>お礼と、口コミの中身への一言が中心。サービスの宣伝や電話番号の連呼はしない。</td></tr>
</table>
<h3>早さ</h3>
<p>口コミには、気づいたときにすぐ返すのが理想です。週に一度など、確かめる日を決めておくと、返し忘れを防げます。ただし、厳しい口コミは、急いで感情的に返すより、社内で事実を確かめてから返すほうが大切です。</p>
<h3>名前で呼ぶか</h3>
<p>口コミには、書いた人の表示名が出ます。「〇〇様」と呼びかけると丁寧ですが、ニックネームや本名らしい名前の場合もあります。本名で呼ぶことで、知り合いに取引が知られてしまうことを嫌がる方もいます。迷うときは、名前を出さずに「このたびはご投稿いただき、ありがとうございます」と始めれば十分です。</p>
<h3>個人情報や取引の中身を書かない</h3>
<p>返信は、だれでも読める場所に出ます。BtoBの会社では、とくに次のことに気をつけましょう。</p>
<ul>
<li>取引先の会社名、担当者の名前</li>
<li>現場の住所、施主の家の場所</li>
<li>注文の数量や金額、図面や仕様など、取引の中身</li>
<li>求職者の場合は、面接に来たこと、選考の結果</li>
</ul>
<p>相手が自分で書いていることでも、会社の側から付け足して書くのは控えます。Googleのコンテンツポリシーでも、本人の同意なく他人の個人情報を載せることは禁止されています。</p>
<h3>宣伝しすぎない</h3>
<p>返信の中に、サービスの紹介やキャンペーンを長く書くと、読む人には「口コミを宣伝に使っている」と映ります。お礼と、口コミに書かれていたことへの一言、そして最後のあいさつ、くらいが読みやすい長さです。</p>
<h3>定型文だけにしない</h3>
<p>毎回同じ文だと、読んでいないように見えます。例文をもとにしつつ、口コミに書かれていたこと（対応の早さ、仕上がり、説明の分かりやすさなど）に一言ふれるだけで、ぐっと伝わり方が変わります。</p>

<h2 id="good">良い口コミへの返信例文（業種別）</h2>
<p>良い口コミには、お礼と、書かれていたことへの一言を返します。例文の「〇〇」の部分は、口コミの中身に合わせて書きかえてください。会社名や人名は例として入れていません。</p>
<h3>製造業：取引先からの口コミ</h3>
<p>例：「短い納期でも相談に乗ってくれて、品質も安定していた」という口コミへの返信</p>
<ul>
<li>このたびはご投稿いただき、ありがとうございます。納期の短いご相談にもかかわらず、品質の面でも評価していただけたこと、現場の職人一同とても励みになります。これからも、ご要望にしっかりお応えできるよう努めてまいります。今後ともよろしくお願いいたします。</li>
</ul>
<p>取引先の品名や数量、納入先などは書かず、「ご相談」「ご要望」とぼかして書くのがポイントです。</p>
<h3>工務店・建設業：施主からの口コミ</h3>
<p>例：「打ち合わせが丁寧で、工事中の連絡もこまめだった」という口コミへの返信</p>
<ul>
<li>温かいお言葉をいただき、ありがとうございます。打ち合わせから完成まで、ご不安のないよう連絡を大切にしてまいりましたので、そのように感じていただけてうれしく思います。お住まいのことで気になる点があれば、いつでもご連絡ください。これからも末永くよろしくお願いいたします。</li>
</ul>
<p>施主の家の場所や、工事の内容（どの部屋を、いくらで）などは書きません。完成後もつながりが続く業種なので、「いつでもご連絡ください」と添えると安心感が伝わります。</p>
<h3>運送業：荷主からの口コミ</h3>
<p>例：「急な依頼にも対応してくれて、ドライバーの対応も感じがよかった」という口コミへの返信</p>
<ul>
<li>ご投稿いただき、ありがとうございます。急なご依頼にもお応えでき、ドライバーの対応までご評価いただけたこと、本人にも伝えさせていただきます。これからも、安全で確かな輸送を心がけてまいります。またのご相談をお待ちしております。</li>
</ul>
<p>運んだ荷物の中身や行き先、日時は書かないようにしましょう。</p>
<h3>採用：求職者や面接に来た人からの口コミ</h3>
<p>例：「面接で職場を案内してくれて、雰囲気が分かってよかった」という口コミへの返信</p>
<ul>
<li>ご投稿いただき、ありがとうございます。実際の職場を見ていただくことで、働くイメージを持っていただけたならうれしいです。これからも、仕事の中身や職場の様子を、できるだけそのままお伝えできるよう心がけてまいります。</li>
</ul>
<p>面接に来たことや選考の結果は、相手が書いていても、会社の側からはふれません。採用での見られ方については、<a href="../recruit-no-applicants/">求人を出しても応募が来ない中小企業へ｜見直したい6つのことと、ホームページの役目</a>も参考にしてください。</p>
<h3>どの業種でも使える短い返信</h3>
<ul>
<li>ご投稿いただき、ありがとうございます。〇〇についてお褒めの言葉をいただき、社員一同励みになります。今後ともよろしくお願いいたします。</li>
</ul>

<h2 id="star-only">星だけの口コミへの返信例文</h2>
<p>文章がなく、星の数だけが付いた口コミもあります。中身が分からないぶん、短く返せば十分です。</p>
<h3>星が多い場合</h3>
<ul>
<li>高い評価をいただき、ありがとうございます。今後もご期待にお応えできるよう努めてまいります。</li>
</ul>
<h3>星が少ない場合</h3>
<ul>
<li>ご評価いただき、ありがとうございます。ご期待に沿えない点があったのであれば、申し訳ございません。お気づきの点がございましたら、お手数ですが当社の窓口までお知らせいただけますと幸いです。今後の改善に役立ててまいります。</li>
</ul>
<p>星が少ない口コミに返信がないと、読む人に「何か問題があったのでは」と思われがちです。理由が分からなくても、話を聞く姿勢を見せておきましょう。</p>

<h2 id="bad">悪い口コミへの返信例文</h2>
<p>厳しい口コミが付くと、すぐに言い返したくなるかもしれません。ですが、返信を読むのは書いた本人だけではなく、これから依頼を考える人たちです。落ち着いた返信は、かえって会社の信頼につながります。</p>
<h3>返信の前に、社内で事実を確かめる</h3>
<ol>
<li>いつ、どの仕事のことか、心当たりを担当者に確かめる。</li>
<li>口コミに書かれていることのうち、事実のこと、事実と違うこと、受け止め方の違いを分ける。</li>
<li>謝るところと、説明するところを決める。</li>
<li>返信は担当者一人で書かず、社長や責任者が目を通す。</li>
</ol>
<h3>謝るところと、説明するところを分ける</h3>
<p>すべてを謝る必要はありませんが、すべてに言い返すのもよくありません。こちらに落ち度があったところは、言い訳をせずに謝ります。事情があったところは、短く、相手を責めない言い方で説明します。そのうえで、個別に話を聞く窓口を案内し、続きはGoogleマップの上ではなく、直接やりとりするのが基本です。</p>
<h3>例文：連絡が遅かったという口コミ</h3>
<ul>
<li>このたびはご不便をおかけし、申し訳ございません。お問い合わせへの返答が遅くなったこと、ご指摘のとおりです。現在、問い合わせの確認と返答の流れを見直しております。詳しいお話をお聞かせいただけましたら、改めてご説明させていただきますので、お手数ですが当社の窓口までご連絡いただけますと幸いです。</li>
</ul>
<h3>例文：仕上がりや対応に不満があったという口コミ</h3>
<ul>
<li>ご期待に沿えず、申し訳ございません。いただいたご意見は社内で共有し、確認を進めております。状況を詳しくお伺いしたうえで、対応させていただきたいと考えております。お手数ですが、当社の窓口までご連絡いただけますでしょうか。</li>
</ul>
<h3>例文：工事中の音や車両の停め方など、近所の方からの口コミ</h3>
<ul>
<li>ご迷惑をおかけし、申し訳ございません。作業中の音や車両の停め方について、現場の担当者とともに確認し、注意を徹底いたします。お気づきのことがございましたら、当社の窓口までお知らせください。</li>
</ul>
<p>建設業や運送業では、取引のない近所の方から口コミが付くこともあります。取引がないからと放っておかず、ほかの口コミと同じように返信しましょう。</p>
<h3>例文：採用の対応についての口コミ</h3>
<ul>
<li>ご不快な思いをおかけし、申し訳ございません。採用での対応について、いただいたご意見を社内で共有し、改善に努めてまいります。</li>
</ul>
<p>採用に関する口コミでは、選考の理由や、その人とのやりとりの中身は書きません。</p>
<h3>やってはいけない返信</h3>
<ul>
<li>「そのような事実はありません」と強く言い返す、相手を責める。</li>
<li>相手がだれか分かる情報（会社名、現場、やりとりの中身）を書く。</li>
<li>何度もやりとりを続けて、言い争いのようになる。</li>
<li>口コミを消してほしい、書き直してほしいと、見返りを示して頼む。</li>
</ul>

<h2 id="report">事実と違う口コミ、決まりに反する口コミの扱い</h2>
<p>まったく取引のない人の書き込みや、関係のない内容、差別的な言葉、個人情報をさらすものなど、Googleの決まり（コンテンツポリシー）に反する口コミは、Googleに報告できます。</p>
<h3>報告のしかた</h3>
<ol>
<li>ビジネスプロフィールを開く。</li>
<li>「クチコミを読む」を選ぶ。</li>
<li>報告したい口コミの横にある報告のボタンを押す。</li>
<li>理由（スパム、冒とく的な表現など）を選んで、送信する。</li>
</ol>
<p>Googleのヘルプでは、報告された口コミの審査には通常数日かかるとされています。報告した口コミの状況は、Googleの「クチコミ管理ツール」で確かめられます。審査の結果に納得できない場合は、一度だけ再審査を求めることができます。</p>
<h3>削除は保証されない</h3>
<p>消してもらえるのは、Googleの決まりに反している口コミだけです。厳しい意見や、会社にとって都合の悪い内容というだけでは、消してもらえません。報告と並行して、ほかの読み手に向けて、落ち着いた返信をしておくことが大切です。事実と違うことが書かれている場合は、相手を責めずに、「当社で確認したところ、該当する記録が見つかりませんでした。お心当たりがございましたら、当社の窓口までご連絡ください」のように、確かめたことだけを書きましょう。</p>

<h2 id="collect">口コミの増やし方</h2>
<p>口コミは、自分で書くことはできません。お客様に書いてもらう必要があります。Googleは、口コミの数が多く評価の高い会社は、地域の検索結果で上に出やすいと説明しています。決まりを守りながら、少しずつ増やしていきましょう。Googleマップ全体の整え方は、<a href="../meo/">MEO対策とは？自分でできることと、頼むときの相場</a>にまとめています。</p>
<h3>口コミを書く画面へのリンクやQRコードを渡す</h3>
<p>ビジネスプロフィールでは、口コミを書く画面へのリンクやQRコードを作れます。「クチコミを読む」から「クチコミを増やす」を選ぶと、リンクをコピーしたり、QRコードを画像として保存したりできます。Googleのヘルプでは、QRコードは今のところパソコンのブラウザでだけ作れると案内されています。</p>
<p>ヘルプでは、領収書、お礼のメール、チャットの最後に入れたり、QRコードを印刷して掲示したりする使い方が紹介されています。BtoBの会社なら、たとえば次のような場面で使えます。</p>
<ul>
<li>納品や引き渡しのあとに送る、お礼のメール</li>
<li>請求書や納品書に添える案内</li>
<li>工事の引き渡し時に渡す書類</li>
<li>事務所の受付に置く案内</li>
</ul>
<h3>お願いするタイミング</h3>
<p>お願いするのは、仕事が一区切りついたときが自然です。製造業なら納品が終わったあと、工務店なら引き渡しのあと、運送業なら取引が落ち着いたころ、などです。満足していそうな人だけに頼むのではなく、同じタイミングで、すべてのお客様に同じようにお願いしましょう。</p>
<h3>お願いの文面の例（メール）</h3>
<ul>
<li>このたびはご依頼いただき、誠にありがとうございました。今後のサービスの改善のため、よろしければGoogleマップに、当社へのご感想をお寄せいただけますと幸いです。良かった点も、気になった点も、率直にお聞かせください。下記のリンクから投稿いただけます。（リンク）なお、ご投稿は任意です。お忙しいところ恐れ入りますが、よろしくお願いいたします。</li>
</ul>
<p>「良かった点も、気になった点も」と書いておくと、良い口コミだけを選んで頼んでいる、と受け取られにくくなります。</p>

<h2 id="ng">口コミを集めるときに、やってはいけないこと</h2>
<p>Googleのコンテンツポリシーでは、次のようなことが禁止されています。決まりに反すると、ビジネスプロフィールが制限されることがあるとヘルプに書かれています。</p>
<table class="art-table">
<tr><th>やってはいけないこと</th><th>例</th></tr>
<tr><td>見返りを渡す</td><td>口コミを書いてくれたら値引きする、粗品を渡す。悪い口コミを書き直してもらう代わりに何かを渡す。</td></tr>
<tr><td>良い口コミだけを選んでお願いする</td><td>満足していそうな取引先にだけ頼む。</td></tr>
<tr><td>悪い口コミを書かないよう頼む</td><td>「星5つでお願いします」「不満があれば口コミではなく直接」と、悪い口コミを止める。</td></tr>
<tr><td>社員や関係者に書かせる</td><td>社員、元社員、協力会社、顧問など、雇用や契約の関係がある人に書いてもらう。</td></tr>
<tr><td>その場で書くよう求める</td><td>打ち合わせの場で、目の前で書いてもらうよう求める。</td></tr>
<tr><td>実体験のない口コミを載せる</td><td>お金を払って口コミを書いてもらう、複数のアカウントで同じ内容を書く。</td></tr>
</table>
<p>社員に「口コミを何件集めてきて」と数を課すことも、ポリシーで禁止されている行為にあたります。数を急がず、仕事のたびにお願いを続けるのが近道です。</p>

<h2 id="homepage">口コミとホームページをつなげる</h2>
<p>Googleマップで口コミを読んだあと、会社のホームページを見てから問い合わせるかを決める人も少なくありません。口コミで「対応が早い」「説明が丁寧」と書かれていても、ホームページに仕事の内容や問い合わせ先が分かりやすく載っていなければ、そこで止まってしまいます。</p>
<p>口コミは増えてきたのに問い合わせにつながらない場合は、<a href="../no-inquiry/">ホームページから問い合わせが来ない理由｜確かめる順番と、直し方</a>で、確かめる順番を紹介しています。検索での見つけられ方を自分で見直したい方は、<a href="../seo-self/">SEO対策は自分でできる？中小企業が今日から始めるやり方と注意点</a>もあわせてご覧ください。</p>
<p>マツケンスタジオでは、ホームページづくりとあわせて、Googleマップの登録・整備からお手伝いしています。最初の相談から公開後まで同じ担当が付き、公開後の更新や改善も続けられます。</p>

<h2 id="summary">まとめ</h2>
<p>口コミへの返信は、書いてくれた人へのお礼であり、これから依頼を考える人へのメッセージです。オーナー確認を済ませたうえで、なるべく早く、相手が特定される情報を書かず、宣伝しすぎずに返しましょう。悪い口コミには、社内で事実を確かめてから、謝るところと説明するところを分けて、個別に話を聞く窓口を案内します。決まりに反する口コミはGoogleに報告できますが、削除は保証されないので、落ち着いた返信もあわせて残しておきます。口コミを増やすときは、リンクやQRコードを使って、すべてのお客様に同じようにお願いし、見返りを渡したり、選んで頼んだりしない。この積み重ねが、Googleマップで選ばれる会社につながります。</p>
''',
 'faq': [
  ('Googleの口コミに返信するには、何が必要ですか？', 'Googleのヘルプでは、口コミに返信するにはビジネスのオーナー確認が必要とされています。まだの場合は、Googleビジネスプロフィールでオーナー確認を済ませてから返信しましょう。返信は、担当者個人ではなく会社からの返信として表示されます。'),
  ('返信したのに表示されません。なぜですか？', '返信は、Googleの審査を経てから表示されます。ヘルプでは、通常は10分以内ですが、最長で30日ほどかかる場合もあると案内されています。しばらく待ってから確かめましょう。'),
  ('星だけで文章のない口コミにも返信したほうがいいですか？', '返信しておくのがおすすめです。星が多い場合は短いお礼で十分です。星が少ない場合は、理由が分からなくても、お詫びと、窓口へ気軽に連絡してほしいという一言を添えておくと、ほかの読み手にも話を聞く姿勢が伝わります。'),
  ('悪い口コミは消してもらえますか？', 'Googleの決まりに反する口コミは、ビジネスプロフィールから報告できます。ただ、消してもらえるのは決まりに反している口コミだけで、削除は保証されません。厳しい意見というだけでは消えないため、社内で事実を確かめたうえで、落ち着いて返信しておくことが大切です。'),
  ('口コミを書いてくれたお客様に、お礼の品を渡してもいいですか？', 'Googleのポリシーでは、口コミの投稿と引き換えに、お金や割引、無料の商品やサービスなどの見返りを渡すことは禁止されています。お礼は、返信の言葉で伝えましょう。'),
  ('社員や協力会社に口コミを書いてもらうのはだめですか？', 'Googleのポリシーでは、今または過去の雇用関係や契約関係などにもとづく口コミは、利益相反として削除の対象になります。社員に口コミ集めの数を課すことも禁止されています。口コミは、実際に仕事を依頼したお客様に書いてもらうものです。'),
 ],
},
]

